import {ToolRegistry} from './registry.js';
import type {ToolDefinition} from '../../types/ai.js';

describe('ToolRegistry caching', () => {
  it('caches compiled validators for function-valued schemas by schema object reference ([validated by spec.md#L18])', async () => {
    const registry = new ToolRegistry();
    let schemaInstance: Record<string, unknown> = {
      type: 'object',
      properties: {count: {type: 'number'}},
      required: ['count'],
    };

    registry.register(
      () => ({
        name: 'test_tool',
        description: 'test',
        inputSchema: schemaInstance,
      }),
      async () => 'ok'
    );

    // First call uses the original schema (requires count: number)
    let response = await registry.execute('test_tool', {count: 'not-a-number'});
    expect({
      failed: response.result.includes('validation failed'),
      mentionsCount: response.result.includes('count'),
    }).toEqual({
      failed: true,
      mentionsCount: true,
    });

    // Mutate the schema definition but KEEP THE SAME OBJECT REFERENCE
    // ajv wouldn't know it changed if it was cached by object reference!
    schemaInstance.required = [];

    // Second call should STILL fail because the compiled validator was cached by reference!
    response = await registry.execute('test_tool', {count: 'not-a-number'});
    expect(response.result.includes('validation failed')).toBe(true);
  });
});

